'use strict';

/*
 * The README of a workspace scaffolded from the restructured source.
 */

const code = (value) => `\`${value}\``;

function readmeV2(manifest, discovery, sections = []) {
  const lines = [];
  const platforms = manifest.selection.map((s) => s.platform);
  const first = manifest.selection[0];
  const config = manifest.configurations[0]?.name ?? '<configuration>';
  lines.push(`# Test workspace: ${platforms.join(', ')}`, '');
  lines.push(
    'Generated by `micro-os-scaffold` from the restructured µOS++ III source',
    `(${code(manifest.sourceRoot)}). The workspace mirrors the source: the kernel holds`,
    'the whole test harness (`micro-os-plus-iii/tests/`), and the ports and device',
    'packages sit one folder deeper, by architecture. It is self-contained and can be',
    'moved: `run.sh` links its own copies of the packages into each build folder and',
    'never runs `xpm link`.',
    ''
  );

  lines.push('## Selected tests', '', '| Platform | Test | Kind | Selection id |', '| --- | --- | --- | --- |');
  for (const entry of manifest.selection) {
    for (const test of entry.tests) {
      lines.push(`| ${code(entry.platform)} | ${code(test.app)} | ${test.kind} | ${test.selectionId ? code(test.selectionId) : "—"} |`);
    }
  }
  lines.push('', 'Kinds: **board** (`tests/platforms/<platform>/tests/<test>/`), **portable** and', '**suite** (shared, `tests/sources/<test>/`).', '');

  lines.push('## Layout', '', '```text');
  const rows = [
    ['micro-os-plus-iii/', `kernel ${manifest.kernel.version ?? ''}, complete; tests/ pruned to the selection`],
    ...platforms.map((p) => [`  tests/platforms/${p}/`, 'the platform: board code, linker script, openocd.cfg, tests/']),
    ...manifest.packages.map((p) => [`${p.dir}/`, `${p.id.includes('devices-') ? 'device package' : 'port'} ${p.version ?? ''}`]),
    ['run.sh', 'the one entry point'],
    ['scripts/env.sh', 'tool and library paths (generated)'],
    ['scaffold.json', 'the manifest'],
  ];
  const width = Math.max(...rows.map((r) => r[0].length)) + 2;
  for (const [name, what] of rows) lines.push(`${name}${' '.repeat(width - name.length)}${what}`);
  lines.push('```', '');

  lines.push('## Build and run', '', '```bash');
  lines.push('./run.sh list              # build, then list the CTest cases (* = selected)');
  lines.push('./run.sh                   # build, then run the selected tests (no hardware)');
  lines.push(`./run.sh ${first?.apps?.[0] ?? '<test>'}${' '.repeat(Math.max(1, 17 - (first?.apps?.[0] ?? '<test>').length))}# one test, by directory name`);
  lines.push('./run.sh --hwd             # the selected tests, hardware cases included');
  lines.push('./run.sh --hwd-only        # only the hardware cases');
  lines.push('./run.sh all               # every registered case');
  lines.push('./run.sh build             # configure + build only');
  lines.push(`./run.sh -c ${config}`);
  lines.push('```', '');
  lines.push(
    `Configurations: ${manifest.configurations.map((c) => code(c.name)).join(', ')}. The build folder is`,
    '`micro-os-plus-iii/tests/build/<configuration>/`. CTest cases are named',
    '`<platform>-<test>-qemu|hwd|host`; the AArch boards add a `-reset` fixture before each',
    'hardware case, and the QEMU SD-card tests add `-sd-make`/`-sd-remove`. CTest runs them',
    'automatically.',
    '',
    '**Hardware cases** need the board and the probe. CTest starts OpenOCD with the',
    "platform's `openocd.cfg`; the test's `RESULT:` line, through semihosting, is the verdict.",
    'Probe selection: `PROBE=jlink|olimex|cmsis-dap` (AArch Pi boards),',
    '`UOS_HW_ADAPTER_SERIAL=<serial>` when several CMSIS-DAP probes are attached (serials:',
    '`cat /sys/bus/usb/devices/*/serial`), `UOS_HW_ADAPTER_KHZ=<kHz>` for the clock.',
    '',
    'Results: `build/<configuration>/ctest.xml` (JUnit) and `ctest.log` (full output).',
    ''
  );

  lines.push('## Adding to this workspace', '');
  lines.push(
    '| You add | Put it in | Picked up by |',
    '| --- | --- | --- |',
    '| a board test | `micro-os-plus-iii/tests/platforms/<platform>/tests/<name>/*.cpp` | the builder (`tests/board-tests/`) globs one test per folder |',
    "| a test's build settings | the hooks in `.../platforms/<platform>/tests/tests.cmake` (`board_test_defines`, `_sources`, `_includes`, `_libs`, ...) | the builder |",
    '| board code | `.../platforms/<platform>/src/`, `include/` | the platform library |',
    "| a shared test for several boards | `micro-os-plus-iii/tests/sources/<name>/`, named in the platform's `UOS_TESTS_SOURCES` | the builder |",
    '',
    '`./run.sh` re-runs CMake every time, so a new folder is noticed without removing the',
    'build tree. A re-scaffold rebuilds the workspace from the source: keep tests you want to',
    'last in the source repository.',
    ''
  );

  for (const section of sections) if (section) lines.push(section.trimEnd(), '');

  lines.push('## Source', '', '| Repository | Folder | Version | Commit |', '| --- | --- | --- | --- |');
  lines.push(`| kernel | ${code('micro-os-plus-iii')} | ${manifest.kernel.version ?? ''} | ${code(manifest.kernel.commit ?? '-')} |`);
  for (const p of manifest.packages) lines.push(`| ${p.id} | ${code(p.dir)} | ${p.version ?? ''} | ${code(p.commit ?? '-')} |`);
  lines.push('');
  if (manifest.build?.results?.length) {
    lines.push('Build verification when scaffolded:', '');
    for (const r of manifest.build.results) lines.push(`- ${code(r.name)}: ${r.status.toUpperCase()}`);
    lines.push('');
  }

  lines.push('## Regenerate', '', '```bash', 'node bin/scaffold.js \\', `  ${manifest.destination} \\`, `  --source ${manifest.sourceRoot} \\`);
  const tokens = manifest.selection.flatMap((s) => (s.all ? [s.platform] : s.apps.map((a) => `${s.platform}.${a}`)));
  lines.push(`  --select ${tokens.join(',')} \\`);
  for (const option of manifest.regenerateOptions ?? []) lines.push(`  ${option} \\`);
  lines.push('  --yes', '```', '');
  return `${lines.join('\n')}\n`;
}

module.exports = { readmeV2 };
